#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Local Ltac lia ::= ne_lia.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := U1Layout.
Abbreviation SEGS := Ubsan.M.loaded_segments.

Definition OVF_RET1 : Z := 0x93210.
Definition OVF_RET2 : Z := 0x93278.
Definition OVF_RETPC : Z := 0x93198.

Section Overflow.
Context {AC : AllocCeiling}.
  Variable MI : MallocIface SEGS Ly.L.
  Variable ST : StaticsIface SEGS Ly.L.
  Hypothesis MALLOC_STACK_pos : 0 <= MALLOC_STACK MI.
  Hypothesis NEW : new_rule_stmt SEGS Ly.L MI ST (NEW_STACK SEGS Ly.L MI).

  #[local] Notation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).

  Definition OVF_STK : Z := 144 + NEW_STACK SEGS Ly.L MI.

  Definition FUEL : nat := 200%nat.

  Theorem sb_overflow :
    forall (fx : FPState) A (s : LibIface.SX ST) R M model (sp ret sb c : Z) (m : sbuf) (pp hm : Z) (K : TSet),
      callB MI ST A s R M model sp ret OVF_STK -> ro_clear Ly.L M ->
      getr R 10%bv = Z_to_bv 64 sb -> getr R 11%bv = Z_to_bv 64 c -> 0 <= c < 256 ->
      sb_inv A M sb m pp hm -> pp = str_data (sb + 64) m + str_cap m ->
      sp <= sb -> sb + 104 <= 2 ^ 47 -> mdef M sb 104 ->
      str_grow m <= NMAX MI -> roomL MI A (live MI A) (str_grow m) ->
      (forall A' R' M' model' (d' : Z),
          retB MI ST A' s R R' M' model model' ->
          getr R' 10%bv = Z_to_bv 64 c ->
          sb_inv A' M' sb (SLong d' (str_grow m)) (d' + str_cap m + 1) (d' + str_cap m + 1) ->
          mdef M' sb 104 ->
          lapply (live MI A) (LAdd d' (str_grow m) :: sbuf_del m) (live MI A') ->
          eff MI A A' M M' (sp - OVF_STK, sp) (fun a => zwin sb (sb + 104) a \/ sbuf_fp m a \/ zwin d' (d' + str_grow m) a) ->
          srealizes SEGS (cfg fx R' ret M' model') K) ->
      srealizes SEGS (cfg fx R A_SB_OVERFLOW M model) K.
Proof using AC MI ST MALLOC_STACK_pos NEW.
